using UnityEngine;
using UnityEditor;
using UnityEngine.UIElements;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        // Find the HudRoot GameObject in the active scene.
        var hud = GameObject.Find("HudRoot");
        if (hud == null)
        {
            result.Log("HudRoot GameObject not found in current scene.");
            return;
        }
        var doc = hud.GetComponent<UIDocument>();
        if (doc == null || doc.rootVisualElement == null)
        {
            result.Log("UIDocument/root missing on HudRoot.");
            return;
        }
        var root = doc.rootVisualElement;
        // Hit HudState and TimeSystem singletons to confirm fields.
        var hs = Homesteader.UI.HudState.Active;
        result.Log("HudState.Active has " + hs.Toolbar.Count + " toolbar slots.");
        result.Log("HudState.Active.ResourceWater.Amount = " + hs.Resources[Homesteader.UI.ResourceId.Water].Amount);
        var ts = Homesteader.UI.TimeSystem.Instance;
        ts.SetSpeed(Homesteader.UI.HomesteaderSpeed.Speed3X);
        ts.Tick(5.0f);
        var snap = ts.Snapshot();
        result.Log("After 5 real-second tick at 3x: dayOfYear=" + snap.DayOfYear + ", cycleMinute=" + snap.CycleMinute + ", phase=" + snap.Phase);
        // Walk the live UIDocument root to confirm the labels exist.
        var sl = root.Q<Label>("SeasonLabel");
        var dl = root.Q<Label>("DayLabel");
        var cl = root.Q<Label>("ClockLabel");
        result.Log("Season label: " + (sl == null ? "NULL" : ("found, text='" + sl.text + "'")));
        result.Log("Day label: " + (dl == null ? "NULL" : ("found, text='" + dl.text + "'")));
        result.Log("Clock label: " + (cl == null ? "NULL" : ("found, text='" + cl.text + "'")));
        // Walk resource labels.
        var watl = root.Q<Label>("ResourceWaterLabel");
        var elcL = root.Q<Label>("ResourceElectricityLabel");
        result.Log("WaterLabel: " + (watl == null ? "NULL" : ("found, text='" + watl.text + "'")));
        result.Log("ElectricityLabel: " + (elcL == null ? "NULL" : ("found, text='" + elcL.text + "'")));
    }
}
